#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/recursive_qualification_v15_$STAMP"
mkdir -p "$BK"

echo "" | base64 -d > companyos/runtime/recursive_qualification.py
echo "" | base64 -d > scripts/companyos_qualify_recursive
chmod +x scripts/companyos_qualify_recursive
echo "" | base64 -d > tests/test_recursive_qualification_v15.py

echo "[1/7] Compile"
python -m py_compile companyos/runtime/recursive_qualification.py tests/test_recursive_qualification_v15.py

echo "[2/7] Qualification harness tests"
python -m unittest tests.test_recursive_qualification_v15 -v

echo "[3/7] Baseline inventory"
scripts/companyos_expandctl inventory || true

echo "[4/7] Run bounded 4-cycle qualification"
scripts/companyos_qualify_recursive run --cycles 4 --delay 15 | tee .companyos_runtime/recursive_qualification_v15_console.json || true

echo "[5/7] Show report"
scripts/companyos_qualify_recursive report || true

echo "[6/7] Commit/push"
git add companyos/runtime/recursive_qualification.py scripts/companyos_qualify_recursive tests/test_recursive_qualification_v15.py
git diff --cached --quiet || git commit -m "Add bounded recursive self-expansion qualification harness"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[7/7] Final health"
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_RECURSIVE_SELF_EXPANSION_QUALIFICATION_V15=PASS"
